<?php namespace App\Services; use App\Repositories\RepositoryFactory;
final class PortfolioService { public function __construct(private RepositoryFactory $factory){} public function projects(){return $this->factory->projects();} public function skills(){return $this->factory->skills();} public function contacts(){return $this->factory->contacts();} public function admins(){return $this->factory->admins();} public function contact(array $d):array{$d=array_map(fn($v)=>trim(strip_tags((string)$v)),$d);$errors=[];if(strlen($d['name']??'')<2||strlen($d['name'])>100)$errors[]='Name must be 2–100 characters.';if(!filter_var($d['email']??'',FILTER_VALIDATE_EMAIL))$errors[]='Enter a valid email.';if(empty($d['subject'])||strlen($d['subject'])>150)$errors[]='Subject is required and must be under 150 characters.';if(strlen($d['message']??'')<10||strlen($d['message'])>3000)$errors[]='Message must be 10–3000 characters.';if(!$errors)$this->contacts()->save($d);return $errors;} public function validateProject(array $d):array{$errors=[];if(empty($d['title'])||strlen($d['title'])>150)$errors[]='Title is required (max 150).';if(empty($d['description']))$errors[]='Description is required.';if(empty($d['technologies']))$errors[]='Technologies are required.';foreach(['github_url','live_url'] as $f)if(!empty($d[$f])&&!filter_var($d[$f],FILTER_VALIDATE_URL))$errors[]='Enter a valid URL.';return $errors;} }
